{  
  "distractors": [  
    {  
      "text": "It encourages people to buy more new products to replace repaired items.",  
      "why_wrong": "This directly contradicts the text, which states the café’s goal is to reduce waste by fixing items instead of replacing them. Encouraging new purchases would harm the environment, not help it."  
    },  
    {  
      "text": "It increases the number of discarded items because people bring broken things to be repaired.",  
      "why_wrong": "The text clearly says the café reduces waste by repairing items. Bringing items to be repaired does not increase discards—it prevents them."  
    },  
    {  
      "text": "It promotes the use of more energy by requiring volunteers to travel to the community hall.",  
      "why_wrong": "The text says nothing about travel or energy use. The café’s environmental benefit comes from repair, not transportation, and this distractor introduces a false claim not supported by the passage."  
    },  
    {  
      "text": "It leads to higher production of goods because more people are fixing things at home.",  
      "why_wrong": "The text shows people are fixing existing items, not producing new ones. This distractor misrepresents the cause-and-effect relationship and contradicts the goal of reducing consumption."  
    },  
    {  
      "text": "It causes more pollution because repaired items are less safe to use.",  
      "why_wrong": "The text never mentions safety concerns or pollution from repaired items. In fact, it emphasizes the café’s positive environmental impact, making this claim entirely unsupported and illogical."  
    },  
    {  
      "text": "It reduces the need for recycling centers by eliminating all broken household items.",  
      "why_wrong": "The text doesn’t say broken items are eliminated—only that they are repaired. Recycling is not mentioned, and claiming the café removes the need for recycling centers is an overstatement not backed by the text."  
    }  
  ]  
}
